        "sectionId": "boethius-poem-1",
        "source": "Carmina qui quondam studio florente peregi, / Flebilis heu maestos cogor inire modos.",
        "literal": "Poems which once in flourishing zeal I accomplished, / Tearful alas sad am compelled to enter measures.",
        "translations": {
          "chaucer_boe": "Allas! I, wepynge, am constreyned to bygynnen vers of sorwful matere, that whilom in florysschyng studie made delitable ditees.",
          "queen_elizabeth_boe": "I that in florishing study whilom finished carols, / Weeping alas! am driven to begin sad verses.",
          "watts_boe": "I who once wrote songs with eager zest am now compelled in tears to begin sad measures.",
          "relihan_boe": "I who once completed poems in flourishing zeal / Am now forced, weeping alas, to enter mournful measures.",
          "green_boe": "I who once composed songs with eager zest am now driven by grief to begin this sorrowful strain.",
          "slavitt_boe": "I who once in happier times made poems / now must write in tears these bitter verses.",
          "stewart_rand_boe": "I that with youthful heat began to write, / Am forced in weeping strains to take delight.",
          "ref": "Boe.1.m1.1",
          "alfred_boe": "When I had set my mind to making songs of sorrow,",
          "colville_boe": "I that in time of prosperity made pleasant songs,",
          "preston_boe": "I that in youth the joyous measures strung, / And all the smiling joys of nature sung,",
          "duncan_boe": "I who formerly in the flowering time of youth made delightful verses,",
          "ridpath_boe": "I who in the flourishing season of youth composed pleasant songs,",
          "fox_boe": "When I had composed these songs, mourning greatly within my heart,",
          "cooper_boe": "I that in youth's flush joyed in sweet songs,",
          "walsh_boe": "I who once composed songs with eager zest",
          "relihan_rev_boe": "I that in youth's flush joyed in sweet songs,",
          "slavitt_rev_boe": "I who once composed poems with joyful zest,",
          "watts_rev_boe": "I who once wrote songs with eager zest,",
          "marenbon_boe": "I who once composed songs with joyful zest",
          "kline_boe": "I who once wrote songs with eager zest"
        },
        "notes": "The opening elegiac couplet of the Consolation.",
