          "bacon_cam": "For immortality on earth below / Is but the glorious name and fame we know / Won by great deeds that never die away.",
          "bullock_cam": "The immortality on earth conferred / Is but the fame by noble actions stirred, / Which crowns high deeds with everlasting praise.",
          "ref": "Cam.9.89",
          "quillinan_cam": "Are nothing else than the delights and praise / Which make man's life heroic and sublime.",
