          "gilbert_ari": "He tears off his clothes and throws his weapons on the ground: he has no more wits, and against rocks and tree trunks he wages blind and furious war.",
          "hoole_ari": "His garments rent, his armor flung aside, / Bereft of reason by the fatal blow, / Against the silent woods his fury turned, / While frantic madness in his bosom burned.",
